import {BlockRegistry,defaultGrid,validateDocument,canonical} from '../../authoring/editor/kernel.mjs';
import {nodeAt,containsProtected} from '../../authoring/document.mjs';
import {contentURL} from '../../hub-cms/body.mjs';
import {validateAsset,validateMediaUsage} from '../../authoring/media.mjs';
const capabilities=Object.freeze({move:true,resize:true,layer:true,edit:true,remove:false});
const keys=(value,allowed)=>value&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).every(k=>allowed.includes(k));
export function manifestRegistry(){return new BlockRegistry()
 .register({type:'text',label:'Text',icon:'T',catalogue:true,duplicate:true,version:1,minCols:1,minRows:1,capabilities:{...capabilities,remove:true},validate:(c,p)=>keys(c,['slot','path','kind','ref'])&&typeof c.slot==='string'&&Array.isArray(c.path)&&c.path.length>0&&c.path.length<=40&&c.path.every(n=>Number.isInteger(n)&&n>=0)&&typeof c.kind==='string'&&Object.keys(p).length===0})
 .register({type:'image',label:'Image',icon:'▧',catalogue:true,duplicate:true,version:1,minCols:2,minRows:2,capabilities:{...capabilities,remove:true},validate:(c,p)=>keys(c,['assetId','usageRef'])&&typeof c.assetId==='string'&&typeof c.usageRef==='string'&&keys(p,['fit'])&&['contain','cover'].includes(p.fit)})
 .register({type:'button',label:'Button',icon:'▰',catalogue:true,duplicate:true,version:1,minCols:2,minRows:1,capabilities:{...capabilities,remove:true},validate:(c,p)=>keys(c,['label','href'])&&typeof c.label==='string'&&c.label.trim().length>0&&c.label.length<=120&&!!contentURL(c.href)&&keys(p,['variant'])&&['primary','secondary'].includes(p.variant)})
 .register({type:'line',label:'Line',icon:'—',catalogue:true,duplicate:true,version:1,minCols:1,minRows:1,capabilities:{...capabilities,edit:false,remove:true},validate:(c,p)=>Object.keys(c).length===0&&Object.keys(p).length===0});}
export function semanticBlocks(body){const result=[];for(const [slot,doc] of Object.entries(body.slots)){function visit(n,path=[]){if(n.type==='doc'||n.type==='container'){(n.content||[]).forEach((child,i)=>visit(child,[...path,i]));return;}result.push({slot,path,kind:n.type,ref:n.attrs?.ref||null,node:n});}visit(doc);}return result;}
export function initialiseManifest(articleId,body){const doc={schemaVersion:1,id:'article:'+articleId,sections:[]};for(const slot of Object.keys(body.slots)){const s={id:'section:'+slot,policy:'push',order:[],blocks:{},layouts:{desktop:{grid:defaultGrid(),rows:8,placements:{}}}};let row=0;for(const r of semanticBlocks(body).filter(r=>r.slot===slot)){const id='block:'+slot+':'+(r.ref||'path-'+r.path.join('-')),locked=containsProtected(r.node),rows=locked?8:r.kind==='heading'?3:4;s.order.push(id);s.blocks[id]={id,type:'text',version:1,content:{slot:r.slot,path:r.path,kind:r.kind,ref:r.ref},presentation:{},capabilities:Object.fromEntries(Object.entries(capabilities).map(([k,v])=>[k,locked?false:v]))};s.layouts.desktop.placements[id]={source:'generated',value:{col:0,row,cols:24,rows,z:0,visible:true,locked}};row+=rows;}s.layouts.desktop.rows=Math.max(8,row+1);doc.sections.push(s);}return validateDocument(doc,manifestRegistry());}
export function semanticNode(block,body){const c=block.content,n=nodeAt(body.slots[c.slot],c.path);if(n.type!==c.kind||(n.attrs?.ref||null)!==c.ref)throw Error('Composition reference changed; return to the structured editor and save before reopening Conjure.');return n;}
export function approvedImage(block,articleId,assets,usage){const asset=assets.find(a=>a.id===block.content.assetId),reference=usage.find(u=>u.article_id===articleId&&u.asset_id===asset?.id&&u.block_ref===block.content.usageRef);if(!reference)throw Error('Image needs an approved Article Media association.');validateAsset(asset);validateMediaUsage(reference);return {asset,reference};}
export function validateComposition(doc,body,articleId,{assets=[],usage=[]}={}){validateDocument(doc,manifestRegistry());if(doc.id!=='article:'+articleId)throw Error('Composition belongs to another article.');for(const s of doc.sections)for(const b of Object.values(s.blocks)){let locked=!manifestRegistry().get(b);if(b.type==='text'&&b.version===1)locked=containsProtected(semanticNode(b,body));if(b.type==='image'&&b.version===1)approvedImage(b,articleId,assets,usage);if(locked){if(Object.values(b.capabilities).some(Boolean)||Object.values(s.layouts).some(l=>!l.placements[b.id].value.locked||!l.placements[b.id].value.visible))throw Error('Protected/unknown content must remain locked and visible.');}}return doc;}
export const compositionChanged=(before,after)=>canonical(before??null)!==canonical(after??null);
